const browser = globalContext.browser || {};
const query = browser.query || {};
let referrerHost = '';
try {
  const ref = wwLib.getFrontDocument().referrer || '';
  if (ref) referrerHost = new URL(ref).hostname;
} catch (e) {
  referrerHost = '';
}
const breakpoint = browser.breakpoint || 'default';
let deviceType = 'desktop';
if (breakpoint === 'mobile') deviceType = 'mobile';
else if (breakpoint === 'tablet') deviceType = 'tablet';
let browserLanguage = '';
try {
  browserLanguage = wwLib.getFrontWindow().navigator.language || '';
} catch (e) {
  browserLanguage = '';
}
return {
  eventType: context.parameters['eventType'] || 'page_view',
  pagePath: browser.path || '/',
  topicId: context.parameters['topicId'] || '',
  noteId: context.parameters['noteId'] || '',
  utmSource: query.utm_source || '',
  utmMedium: query.utm_medium || '',
  utmCampaign: query.utm_campaign || '',
  referrerHost: referrerHost,
  deviceType: deviceType,
  browserLanguage: browserLanguage
};

